import{_ as o,o as e,c as d,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"CC Switch 接入 Codex 桌面版（GUI）：Windows 和 Mac 都能用中转站","description":"","frontmatter":{"title":"CC Switch 接入 Codex 桌面版（GUI）：Windows 和 Mac 都能用中转站","date":"2026-09-18T20:00:00.000Z","tags":["CC Switch","Codex","中转站","教程"],"categories":["技术折腾"]},"headers":[],"relativePath":"guide/02-codex.md","filePath":"guide/02-codex.md"}'),c={name:"guide/02-codex.md"};function a(l,t,r,n,s,C){return e(),d("div",null,[...t[0]||(t[0]=[i('<blockquote><p>生命不息，折腾不止。</p></blockquote><p>Codex 现在是<strong>有图形界面的桌面应用</strong>了（不用再窝在终端里）。这篇教小白：在 Windows 和 Mac 上装好 Codex 桌面版，再用 CC Switch 把 AI 中转站接进去——重点是 Codex 桌面版<strong>没有内置切换供应商的功能，CC Switch 几乎是必须的</strong>。</p><h2 id="一、codex-桌面版是个啥" tabindex="-1">一、Codex 桌面版是个啥 <a class="header-anchor" href="#一、codex-桌面版是个啥" aria-label="Permalink to &quot;一、Codex 桌面版是个啥&quot;">​</a></h2><p>Codex 是 OpenAI 出的 AI 编程智能体。现在它有<strong>桌面应用（GUI）</strong>，打开就是一个图形窗口，能：</p><ul><li>同时跑多个 AI 代理线程（每个线程独立干活）</li><li>集成了 Git（能看代码改动、随时回退）</li><li>有 Plan 模式（先规划再动手）</li></ul><p><strong>支持平台：</strong></p><table tabindex="0"><thead><tr><th>系统</th><th>要求</th></tr></thead><tbody><tr><td>macOS</td><td><strong>必须 Apple Silicon</strong>（M1/M2/M3/M4），Intel Mac 不支持</td></tr><tr><td>Windows</td><td>2026 年 3 月起支持，下载安装包即可</td></tr><tr><td>Linux</td><td>没有图形版，用 Codex CLI（终端版）</td></tr></tbody></table><h2 id="二、准备工作" tabindex="-1">二、准备工作 <a class="header-anchor" href="#二、准备工作" aria-label="Permalink to &quot;二、准备工作&quot;">​</a></h2><blockquote></blockquote><p>（2 分钟）</p><ol><li><strong>中转站 API Key</strong>：登录你的中转站（如 ai.aklibk.com）→ 后台 → API Keys → 创建，复制 <code>sk-</code> 开头的 Key</li><li><strong>下载 Codex 桌面版</strong>：去 OpenAI 官网（chatgpt.com 或 Codex 官方页面）下载 macOS / Windows 安装包</li><li><strong>下载 CC Switch</strong>：官网 ccswitch.io 或 GitHub Releases（只认官方渠道！）</li></ol><blockquote><p>macOS 如果提示&quot;无法打开，因为来自身份不明的开发者&quot;：右键安装包 → 打开 → 确认即可（Gatekeeper 首次拦截，正常现象）。</p></blockquote><h2 id="三、在-cc-switch-里添加-codex-供应商" tabindex="-1">三、在 CC Switch 里添加 Codex 供应商 <a class="header-anchor" href="#三、在-cc-switch-里添加-codex-供应商" aria-label="Permalink to &quot;三、在 CC Switch 里添加 Codex 供应商&quot;">​</a></h2><p><strong>为什么必须用 CC Switch？</strong> Codex 桌面版的界面里<strong>没有切换供应商的按钮</strong>，它只读电脑里的配置文件（<code>~/.codex/auth.json</code> 和 <code>config.toml</code>）。想用中转站，就得有人帮你改配置——这个人就是 CC Switch。</p><ol><li>打开 CC Switch</li><li>左侧切换器选 <strong>Codex</strong> 应用</li><li>点右上角 <strong>+</strong> 号</li><li>预设选 <strong>自定义</strong></li><li>填关键信息： <ul><li><strong>名称</strong>：如 <code>我的中转站</code></li><li><strong>API 地址（Base URL）</strong>：<code>https://ai.aklibk.com/v1</code>（OpenAI 兼容端点）</li><li><strong>API Key</strong>：粘贴中转站的 <code>sk-</code> Key</li><li><strong>模型</strong>：填一个支持的模型，如 <code>gpt-5.2</code> 或 <code>gpt-4o</code></li></ul></li><li>点 <strong>添加</strong>，再点一下这个供应商（选中 = 生效）</li></ol><blockquote></blockquote><blockquote><p>CC Switch 会自动写好 Codex 的 <code>auth.json</code>（存 <code>OPENAI_API_KEY</code>）和 <code>config.toml</code>（模型提供商 custom + base_url + wire_api responses），全程不用你碰文件。</p></blockquote><h2 id="四、切换并打开-codex-桌面版" tabindex="-1">四、切换并打开 Codex 桌面版 <a class="header-anchor" href="#四、切换并打开-codex-桌面版" aria-label="Permalink to &quot;四、切换并打开 Codex 桌面版&quot;">​</a></h2><ol><li>确认 CC Switch 里选中的是你刚加的中转站供应商</li><li><strong>重启 Codex 桌面版</strong>（关键！重启才会读新配置）</li><li>打开 Codex 窗口，随便问一句</li></ol><blockquote></blockquote><p>&quot;你好&quot;——能回复就成功了</p><blockquote><p>桌面版和命令行版（Codex CLI）<strong>共享同一套配置</strong>：你在 CC Switch 里改一次，两边重启后都生效。桌面版当&quot;图形面板&quot;用，CLI 当&quot;脚本自动化&quot;用，互不冲突。</p></blockquote><p><strong>想切回官方 ChatGPT 账号？</strong> 在 CC Switch 里点回 Codex 官方的供应商，重启 Codex 即可。</p><h2 id="五、常见问题" tabindex="-1">五、常见问题 <a class="header-anchor" href="#五、常见问题" aria-label="Permalink to &quot;五、常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>问题</th><th>解决</th></tr></thead><tbody><tr><td>macOS 打不开/提示未信任</td><td>右键安装包 → 打开 → 确认（Intel Mac 不支持，别硬装）</td></tr><tr><td>切换了没反应</td><td>必须重启 Codex 桌面版</td></tr><tr><td>报 API Key invalid</td><td>确认 CC Switch 填的 Key 是 <code>sk-</code> 开头的完整 Key（配置里会自动写成 <code>OPENAI_API_KEY</code> 全大写）</td></tr><tr><td>报模型不存在</td><td>换成中转站后台实际提供的模型名</td></tr><tr><td>用 Linux</td><td>没有图形版，用 Codex CLI（CC Switch 也能管它的配置）</td></tr></tbody></table><h2 id="六、总结" tabindex="-1">六、总结 <a class="header-anchor" href="#六、总结" aria-label="Permalink to &quot;六、总结&quot;">​</a></h2><p>Codex 桌面版接中转站：<strong>下载 CC Switch → Codex 面板添加（填地址+Key）→ 切换 → 重启 Codex 桌面版</strong>。因为桌面版没内置切换器，CC Switch 这一步逃不掉，但用起来就是&quot;点一下&quot;的事。</p><p>Claude、GPT、Gemini 全家桶一个 Key 通吃？试试 Aklibk API 中转站（ai.aklibk.com），国内直连、免绑卡、人民币按量付费。</p><blockquote><p>下一篇预告：Claude Code CLI 的接入教程，同样是小白三步走。</p></blockquote>',29)])])}const g=o(c,[["render",a]]);export{u as __pageData,g as default};
